    const doc = t.hostDoc || await ue(); if (!doc) return;
    nodes = await nxUnwrapSafeNodes(await doc.querySelectorAll('[data-inray-bake]:hover:not([x-inray-history-ready]),[x-inray-bake]:hover:not([x-inray-history-ready])'));
